#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn balanced() {
        assert!(is_balanced("{[()]}()"));
    }

    #[test]
    fn interleaved() {
        assert!(!is_balanced("([)]"));
    }

    #[test]
    fn empty() {
        assert!(is_balanced(""));
    }

    #[test]
    fn unclosed() {
        assert!(!is_balanced("(("));
    }

    #[test]
    fn extra_closer() {
        assert!(!is_balanced("())"));
        assert!(!is_balanced("]"));
    }
}
